using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Media.DBContext.Models;

/// <summary>
/// Represents a rule which allows the clients of a group to share records.
/// Values of one criterion are combined with OR, criteria with AND. An empty criterion matches everything. A rule without criteria matches
/// nothing, unless it matches all records.
/// </summary>
[Table("share_rules")]
public class ShareRule
{
  /// <summary>
  /// Primary key. Autogenerated.
  /// </summary>
  [Key]
  public Guid ShareRuleId { get; set; }

  /// <summary>
  /// The groups whose clients the rule allows to share records.
  /// </summary>
  public ICollection<Group> Groups { get; set; } = [];

  /// <summary>
  /// True, if the rule matches all records and has no criteria.
  /// </summary>
  public bool AllRecords { get; set; }

  /// <summary>
  /// Genres the rule matches.
  /// </summary>
  public ICollection<Genre> Genres { get; set; } = [];

  /// <summary>
  /// Albums the rule matches.
  /// </summary>
  public ICollection<Album> Albums { get; set; } = [];

  /// <summary>
  /// Artists the rule matches.
  /// </summary>
  public ICollection<Artist> Artists { get; set; } = [];
}
